Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='movetonew', at=datetime(2026, 11, 2, 0, 0, 0), actor='owner', title='Move to the new design and delete the old in the same change; keep no converters, carries or shims', body='A change that replaces a mechanism migrates every user of the old one in the same pull request, or in parallel pull requests that land together, and deletes the old one. There is no converter, no reader of the old form beside the new one, no flag, and no deprecation period. A stored format that changes ships a one-time migration verb, run once with a scratch-copy proof, and the old reader is deleted with it. Rewriting is cheap; carrying two designs is not. The gate still runs on every change.', rationale='The owner, 2026-11-02: move to the new thing and fix what breaks, keep no old burdens, and rewrite whatever we need to.', supersedes=('nobackcompat',)))